function u_c_out = mfun_gfl_current_controller(i_c_ref_in, fbk_in, p)
%MFUN_GFL_CURRENT_CONTROLLER Block CurrentController of the control system.
%   CurrentController of motulator. Generated by motulator_export from the MATLAB port
%   of motulator. The parameters are the fields of the struct p (from the mask, [] as
%   NaN). The state is in persistent variables.
persistent self
if isempty(self)
    self = gfl_current_controller(p.L, p.alpha_c, p.alpha_i);
end
i_c_ref = complex_in(i_c_ref_in);
fbk = gfl_feedbacks_unpack(fbk_in);
[self, u_c] = complex_pi_compute_output(self, i_c_ref, fbk.i_c, fbk.u_g);
u_c_out = complex_out(u_c);
self = complex_pi_update(self, p.T_s, fbk.u_c, fbk.w_c);
end

function s = gfl_feedbacks_unpack(u)
%GFL_FEEDBACKS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_c', complex(u(1), u(2)), ...
    'u_c', complex(u(3), u(4)), ...
    'u_g', u(5), ...
    'u_g_meas', complex(u(6), u(7)), ...
    'theta_c', u(8), ...
    'w_g', u(9), ...
    'w_c', u(10), ...
    'p_g', u(11), ...
    'q_g', u(12), ...
    'eps', u(13));
end

function z = complex_in(u)
%COMPLEX_IN Complex number from a signal [real part; imaginary part].
z = complex(u(1), u(2));
end

function y = complex_out(z)
%COMPLEX_OUT Signal [real part; imaginary part] of a complex number.
y = [real(z); imag(z)];
end

function self = complex_pi_init(k_p, k_i, k_t)
%COMPLEX_PI_INIT 2DOF synchronous-frame complex-vector PI controller
%   (ComplexPIController).
self = struct('k_p', k_p, 'k_t', k_t, 'alpha_i', k_i/k_t, 'u_i', complex(0), ...
    'v', complex(0));
end

function [self, u] = complex_pi_compute_output(self, i_ref, i, u_ff)
%COMPLEX_PI_COMPUTE_OUTPUT Controller output.
% Disturbance input estimate
self.v = self.u_i - (self.k_p - self.k_t)*i + u_ff;
u = self.k_t*(i_ref - i) + self.v;
end

function self = complex_pi_update(self, T_s, u, w_c)
%COMPLEX_PI_UPDATE Update the integral state with the realized output u.
self.u_i = self.u_i + T_s*(self.alpha_i + 1i*w_c)*(u - self.v);
end

function ctrl = gfl_current_controller(L, alpha_c, alpha_i)
%GFL_CURRENT_CONTROLLER Current controller (CurrentController), a 2DOF PI
%   controller with the gains from the bandwidths and the inductance (alpha_i = NaN
%   means alpha_c).
if isnan(alpha_i)
    alpha_i = alpha_c;
end
k_t = alpha_c*L;
k_i = alpha_c*alpha_i*L;
k_p = (alpha_c + alpha_i)*L;
ctrl = complex_pi_init(k_p, k_i, k_t);
end
